// A class with a user-declared destructor.
class NonMovable {
public:
    // A user-declared destructor, even if empty, triggers the rule.
    ~NonMovable() { /* e.g., logging or cleanup */ }

    // Because a destructor is user-declared, the compiler
    // does NOT generate move operations.
    // MyType(MyType&&) is implicitly deleted.
    // MyType& operator=(MyType&&) is implicitly deleted.

    // Copy operations are still generated (for backward compatibility).
    NonMovable(const NonMovable&) = default;
    NonMovable& operator=(const NonMovable&) = default;
};

// To make a similar class movable, you must be explicit.
class Movable {
public:
    ~Movable() { /* ... */ }

    // Explicitly request the default move operations.
    Movable(Movable&&) = default;
    Movable& operator=(Movable&&) = default;

    // Note: declaring move ops suppresses copy op generation.
    // We must also default them if we want the class to be copyable.
    Movable(const Movable&) = default;
    Movable& operator=(const Movable&) = default;
};
